/** Displays a keyboard-trapped restore confirmation before any local data replacement. */
function RestoreConfirmation({ backup, busy, onCancel, onConfirm }: { backup: ValidatedBackup; busy: boolean; onCancel: () => void; onConfirm: () => void }) {
  const root = useRef<HTMLElement>(null)
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null
    root.current?.querySelector<HTMLButtonElement>('button')?.focus()
    const oldOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => { document.body.style.overflow = oldOverflow; previous?.focus() }
  }, [])
  /** Keeps keyboard and Escape behavior within the confirmation sheet. */
  function handleKeys(event: KeyboardEvent<HTMLElement>) {
    if (event.key === 'Escape' && !busy) onCancel()
    if (event.key !== 'Tab') return
    const buttons = Array.from(root.current?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)') ?? [])
    const first = buttons[0]
    const last = buttons.at(-1)
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus() }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus() }
  }
  return <div className="modal-backdrop" onMouseDown={(event) => { if (!busy && event.target === event.currentTarget) onCancel() }}><section ref={root} className="dialog" role="dialog" aria-modal="true" aria-labelledby="restore-title" onKeyDown={handleKeys}><header className="dialog-header"><h2 id="restore-title">Replace local records?</h2><button className="icon-button" aria-label="Cancel restore" onClick={onCancel} disabled={busy}><X size={20} /></button></header><p className="backup-copy">{backupSummary(backup)}</p><p className="backup-copy">Schema {backup.schemaVersion ?? 'legacy'}{backup.exportedAt ? ` · Exported ${new Date(backup.exportedAt).toLocaleString()}` : ''}</p><p className="backup-copy">All current records will be replaced. An on-device recovery snapshot must be saved successfully before restore can proceed.</p><footer className="dialog-actions"><button className="button secondary" onClick={onCancel} disabled={busy}>Cancel</button><button className="button primary" onClick={onConfirm} disabled={busy}>{busy ? 'Restoring…' : 'Confirm restore'}</button></footer></section></div>
}

